    "definition": "В медицинской дерматологии — бактериальная инфекция глубоких слоёв кожи и подкожной клетчатки, проявляющаяся распространяющимся покраснением, теплом, отёком и болезненностью. Не следует путать с косметическим «целлюлитом».",
    "miniDefinition": "Бактериальная инфекция глубоких слоёв кожи и подкожной клетчатки; не то же, что косметический целлюлит."
