    "category": "Дерматология",
    "difficulty": "средний",
    "definition": "Педикулёз — заражение человека вшами, которые живут на волосистой части головы, теле или в области лобка. Зуд связан с реакцией кожи на укусы; способ передачи зависит от вида вшей.",
    "miniDefinition": "Заражение вшами, обычно сопровождающееся зудом."
