    "type": "состояние",
    "category": "Дерматология",
    "difficulty": "легкий",
    "definition": "«Лишай» — бытовое название нескольких кожных заболеваний с разными причинами: грибковыми, вирусными, воспалительными или иммунными. По одному слову нельзя определить конкретную болезнь.",
    "miniDefinition": "Общее название разных заболеваний кожи, а не один диагноз."
