    "norm": "склеродермия",
    "type": "состояние",
    "category": "Ревматология",
    "difficulty": "сложный",
    "definition": "Склеродермия — заболевание из спектра состояний, при которых избыточное накопление коллагена вызывает уплотнение кожи; при системной форме могут поражаться сосуды и внутренние органы.",
