    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "легкий",
    "definition": "Рана — нарушение целостности кожи, слизистой или глубжележащих тканей. Раны различаются по механизму, глубине и загрязнению; возможные осложнения включают кровотечение, инфекцию и повреждение нервов или сосудов.",
    "miniDefinition": "Нарушение целостности тканей."
