    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "легкий",
    "definition": "Свищ — патологический канал между двумя органами, полостями или органом и поверхностью тела. Он может возникать при воспалении, травме, опухоли или после операции; значение зависит от его расположения и содержимого.",
    "miniDefinition": "Патологический канал между органами или с поверхностью тела."
