    "norm": "тампонада",
    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "средний",
    "definition": "Тампонада — сдавление органа или полости накопившимся содержимым. Например, тампонада сердца возникает при повышении давления в перикарде из-за жидкости и мешает наполнению камер сердца.",
    "miniDefinition": "Сдавление органа содержимым полости; пример — тампонада сердца."
