    "norm": "ампутация",
    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "средний",
    "definition": "Ампутация — хирургическое удаление части или всей конечности либо другого выступающего сегмента тела. Выполняется по жизненным показаниям или при необратимом повреждении; уровень выбирают с учётом жизнеспособности тканей и функции.",
    "miniDefinition": "Хирургическое удаление части конечности или органа."
