    "norm": "дренирование",
    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "сложный",
    "definition": "Дренирование — отведение жидкости, крови, гноя или воздуха из раны, полости либо органа с помощью дренажа или созданного хирургического пути. Цель — устранить скопление содержимого и облегчить контроль за ним.",
