    "norm": "лапаротомия",
    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "средний",
    "definition": "Лапаротомия — хирургическое вскрытие брюшной полости через разрез брюшной стенки для осмотра или выполнения операции. В отличие от лапароскопии, обычно требует более крупного доступа.",
    "miniDefinition": "Открытый хирургический доступ в брюшную полость."
