    "norm": "лапароскопия",
    "type": "состояние",
    "category": "Хирургия",
    "difficulty": "сложный",
    "definition": "Лапароскопия — осмотр брюшной полости с помощью оптического инструмента через небольшие разрезы; через дополнительные порты можно выполнять операции. Это малоинвазивный доступ, но он всё равно связан с хирургическими рисками.",
    "miniDefinition": "Осмотр и операция в брюшной полости через небольшие разрезы."
