    "category": "Онкология",
    "difficulty": "легкий",
    "definition": "Опухоль — патологическое разрастание клеток, формирующее тканевое образование. Опухоли бывают доброкачественными и злокачественными; термин сам по себе не определяет биологическое поведение без уточнения диагноза.",
    "miniDefinition": "Патологическое разрастание клеток; бывает доброкачественным или злокачественным."
