    "category": "Онкология",
    "difficulty": "средний",
    "definition": "Неоплазия — новое патологическое разрастание клеток с автономным или нарушенно регулируемым ростом. Неоплазма может быть доброкачественной либо злокачественной; для классификации используют морфологию и другие данные.",
    "miniDefinition": "Патологический рост клеток, формирующий новообразование."
