    "category": "Онкология",
    "difficulty": "сложный",
    "definition": "Новообразование — тканевое образование, возникшее вследствие патологического роста клеток. Оно может быть доброкачественным, злокачественным или иметь неопределённое поведение; точный тип устанавливают по диагностическим данным.",
    "miniDefinition": "Образование, возникшее из патологически растущих клеток."
