    "definition": "Дисплазия — нарушение созревания, организации и внешнего вида клеток в ткани. Значение зависит от органа и степени изменений; некоторые формы являются предраковыми, но дисплазия не равнозначна инвазивному раку.",
    "miniDefinition": "Нарушение созревания и строения клеток ткани."
